"""Phase B gate: actual UI before replacing recruiting. Fresh fictional data only."""
import os,json,unittest,uuid
from pathlib import Path
from playwright.sync_api import sync_playwright
BASE=os.environ.get('ARENA_QA_BASE','http://127.0.0.1:3004');ENGINE=os.environ.get('PROFILE_BROWSER','chromium');OUT=Path('docs/profile-reconstruction-20261117/after');OUT.mkdir(parents=True,exist_ok=True)
class Foundation(unittest.TestCase):
 @classmethod
 def setUpClass(cls):cls.pw=sync_playwright().start();cls.browser=getattr(cls.pw,ENGINE).launch(executable_path=os.environ.get('WEBKIT_PATH') if ENGINE=='webkit' else '/usr/bin/chromium',headless=True)
 @classmethod
 def tearDownClass(cls):cls.browser.close();cls.pw.stop()
 def setUp(self):self.context=self.browser.new_context(viewport={'width':810,'height':1080});self.page=self.context.new_page();self.errors=[];self.page.on('pageerror',lambda e:self.errors.append(str(e)))
 def tearDown(self):self.assertEqual(self.errors,[]);self.context.close()
 def state(self):return self.page.evaluate('JSON.parse(localStorage.getItem("arenaPathway.v2"))')
 def create(self,name,sport):
  p=self.page;p.goto(BASE+'/build?new=1');p.wait_for_selector('#athlete-basics:not([disabled])');p.locator('#nickname').fill(name);p.locator('#sport').select_option(sport);p.locator('#guardian').check();p.locator('#club-team').fill('Fictional family team');p.get_by_role('button',name='Save athlete profile',exact=False).click();p.wait_for_selector('.athlete-masthead');return self.state()['active']
 def shot(self,name):
  self.page.wait_for_function('()=>!document.querySelector("#toast")?.textContent');self.page.evaluate('()=>{document.activeElement?.blur();document.querySelector(".skip").style.visibility="hidden";}');self.page.screenshot(path=str(OUT/(ENGINE+'-'+name+'.png')),full_page=True,animations='disabled');self.page.evaluate('()=>document.querySelector(".skip").style.removeProperty("visibility")')
 def views(self,name):
  for label,w,h in [('desktop',1440,900),('ipad-portrait',810,1080),('ipad-landscape',1024,768),('phone',390,844)]:
   self.page.set_viewport_size({'width':w,'height':h});self.assertFalse(self.page.evaluate('document.documentElement.scrollWidth>innerWidth+1'));self.shot(name+'-'+label)
  self.page.set_viewport_size({'width':810,'height':1080})
 def test_profile_gallery_edit_remove_and_reload(self):
  p=self.page;ids=[self.create(n,s) for n,s in [('Morgan Demo','lacrosse'),('Jamie Demo','swimming'),('Alex Demo','volleyball')]];p.goto(BASE+'/my-pathway?view=family');p.wait_for_selector('.athlete-player-card');self.assertEqual(p.locator('.athlete-player-card').count(),3);self.views('family-gallery');p.locator('.athlete-player-card').first.get_by_role('link',name='View Profile',exact=True).click();p.wait_for_selector('.athlete-story');self.assertEqual(self.state()['active'],ids[0])
  for section,label,value in [('About Me','About Me','Fictional athlete: I enjoy building my game with my team.'),('Education','High school','Fictional Academy'),('Achievements','Achievements (one per line)','Fictional team leadership award')]:
   p.get_by_role('button',name='Edit '+section,exact=True).click();d=p.get_by_role('dialog');d.get_by_label(label,exact=True).fill(value);d.get_by_role('button',name='Save '+section,exact=True).click();p.wait_for_selector('.athlete-story');self.assertEqual(p.get_by_role('dialog').count(),0)
  self.views('athlete-profile');p.reload();p.wait_for_selector('.athlete-story');self.assertIn('Fictional Academy',p.locator('#overview').inner_text());self.assertIn('Fictional team leadership award',p.locator('#overview').inner_text());self.assertEqual(self.state()['active'],ids[0]);p.goto(BASE+'/my-pathway?view=family');p.wait_for_selector('.athlete-player-card');card=p.locator('.athlete-player-card').first;card.get_by_label('Manage Morgan Demo',exact=True).click();card.get_by_role('button',name='Delete Athlete',exact=True).click();d=p.get_by_role('dialog');self.assertTrue(d.get_by_role('button',name='Remove athlete',exact=True).is_disabled());d.get_by_label('Athlete name confirmation',exact=True).fill('Morgan');self.assertTrue(d.get_by_role('button',name='Remove athlete',exact=True).is_disabled());d.get_by_role('button',name='Keep athlete',exact=True).click();self.assertEqual(len(self.state()['profiles']),3)
  card.get_by_role('button',name='Delete Athlete',exact=True).click();d=p.get_by_role('dialog');d.get_by_label('Athlete name confirmation',exact=True).fill('Morgan Demo');self.shot('deletion-confirmation');d.get_by_role('button',name='Remove athlete',exact=True).click();p.wait_for_function('JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles.length===2');p.reload();p.wait_for_selector('.athlete-player-card');self.assertEqual(p.locator('.athlete-player-card').count(),2);self.assertEqual(self.state()['archivedProfiles'][0]['profile']['id'],ids[0]);self.assertEqual([x['id'] for x in self.state()['profiles']],ids[1:]);p.goto(BASE+'/my-ap?scenario=local&section=family');p.wait_for_selector('.ap-family-grid');self.assertNotIn('Morgan Demo',p.locator('.ap-family-grid').inner_text());(OUT.parent/(ENGINE+'-profile-foundation.json')).write_text(json.dumps({'createdIDs':ids,'removedID':ids[0],'remainingIDs':ids[1:],'reload':True,'pageErrors':self.errors},indent=2)+'\n')
 def test_media_portrait_archive_and_stale_writer(self):
  import base64
  p=self.page;first=self.create('Media Demo','lacrosse');stale=self.state();image=p.evaluate("""()=>{const c=document.createElement('canvas');c.width=400;c.height=400;const x=c.getContext('2d');x.fillStyle='#17243a';x.fillRect(0,0,400,400);x.fillStyle='white';x.font='bold 100px sans-serif';x.fillText('MD',110,235);return c.toDataURL('image/png').split(',')[1];}""");payload={'name':'fictional-monogram.png','mimeType':'image/png','buffer':base64.b64decode(image)}
  p.locator('#athlete-photo').set_input_files(payload);p.wait_for_function('()=>!!JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].avatarDataUrl');p.locator('#profile-nav').get_by_role('link',name='Media',exact=True).click();p.get_by_role('button',name='Add Media',exact=True).click();p.locator('#media-upload').set_input_files(payload);p.locator('#media-caption').fill('Fictional athlete monogram');p.get_by_role('button',name='Save media',exact=True).click();p.wait_for_selector('.family-media-gallery img');p.locator('#profile-nav').get_by_role('link',name='Profile',exact=True).click();p.wait_for_selector('#profile-featured-media img');p.get_by_role('button',name='Choose Featured Media',exact=True).click();d=p.get_by_role('dialog');d.get_by_role('button',name='Fictional athlete monogram',exact=True).click();d.get_by_role('button',name='Save featured media',exact=True).click();p.wait_for_function('JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].featuredMediaIds.length===0');p.reload();p.wait_for_selector('.athlete-story');self.assertEqual(p.locator('#profile-featured-media img').count(),0);self.assertFalse(self.state()['profiles'][0]['recruiting'].get('highlightIds'));p.get_by_role('button',name='Choose Featured Media',exact=True).click();d=p.get_by_role('dialog');d.get_by_role('button',name='Fictional athlete monogram',exact=True).click();d.get_by_role('button',name='Save featured media',exact=True).click();p.wait_for_selector('#profile-featured-media img');self.shot('profile-with-owned-monogram')
  second=self.create('Other Media Demo','swimming');p.locator('#profile-nav').get_by_role('link',name='Media',exact=True).click();p.get_by_role('button',name='Add Media',exact=True).click();p.locator('#media-upload').set_input_files(payload);p.locator('#media-caption').fill('Unrelated athlete monogram');p.get_by_role('button',name='Save media',exact=True).click();p.wait_for_selector('.family-media-gallery img');p.goto(BASE+'/my-pathway?view=family');p.wait_for_selector('.athlete-player-card');card=p.locator('.athlete-player-card').first;card.get_by_label('Manage Media Demo',exact=True).click();card.get_by_role('button',name='Delete Athlete',exact=True).click();d=p.get_by_role('dialog');d.get_by_label('Athlete name confirmation',exact=True).fill('Media Demo');d.get_by_role('button',name='Remove athlete',exact=True).click();p.wait_for_function('JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles.length===1');proof=p.evaluate("""async ids=>{const {listMedia}=await import('/assets/media-library.js');return Promise.all(ids.map(async id=>({id,items:(await listMedia(id)).map(m=>({id:m.id,owner:m.athleteId,bytes:m.blob.size}))})));}""",[first,second]);self.assertEqual([len(x['items']) for x in proof],[1,1]);self.assertTrue(all(x['items'][0]['bytes']>0 for x in proof));self.assertEqual(self.state()['archivedProfiles'][0]['profile']['featuredMediaIds'],[proof[0]['items'][0]['id']])
  stale['profiles'].append(self.state()['profiles'][0]);p.evaluate("""async stale=>{const {persist}=await import('/assets/state.js');persist(localStorage,stale);}""",stale);p.reload();p.wait_for_selector('.athlete-player-card');self.assertEqual(p.locator('.athlete-player-card').count(),1);self.assertEqual(self.state()['profiles'][0]['id'],second);(OUT.parent/(ENGINE+'-media-removal-proof.json')).write_text(json.dumps({'archivedID':first,'unrelatedID':second,'retainedBlobs':proof,'staleWriterResurrection':False},indent=2)+'\n')
if __name__=='__main__':unittest.main(verbosity=2)
